private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int start = i;
    while (bb.remaining() >= 3) {
        int b1 = bb.get() & 0xFF;
        int b2 = bb.get() & 0xFF;
        int b3 = bb.get() & 0xFF;
        int value = (b1 << 16) | (b2 << 8) | b3;
        char c = (char) value;
        sb.append(c);
        i += 3;
    }
    while (i < bb.limit()) {
        int b = bb.get() & 0xFF;
        sb.append((char) b);
        i++;
    }
    return i;
}
