private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node.getLeft() == null) {
        throw new IllegalArgumentException("Node has no left child to rotate.");
    }
    TreeNode<T> newParent = node.getLeft();
    node.setLeft(newParent.getRight());
    newParent.setRight(node);
    node.setHeight(node.getHeight() - Math.max(newParent.getHeight() - 1, node.getLeft().getHeight()));
    newParent.setHeight(newParent.getHeight() - Math.max(newParent.getHeight() - 1, node.getHeight()));
    return newParent;
}
