private static void addJarToFileSystem(URLClassLoader classLoader, File jarFile) throws IOException {
    URL jarUrl = URL.fromFile(jarFile);
    classLoader.addURL(jarUrl);
    JarFile jar = new JarFile(jarFile);
    for (JarEntry entry : jar.entries()) {
        if (entry.isDirectory()) {
            continue;
        }
        URL resourceUrl = classLoader.getResource(entry.getName());
        if (resourceUrl != null) {
            JarEntry newJarEntry = new JarEntry(entry.getName());
            InputStream inputStream = resourceUrl.openStream();
            JarOutputStream outputStream = new JarOutputStream(classLoader.getResourceAsStream("/META-INF/services/" + entry.getName()));
            copyStream(inputStream, outputStream);
            inputStream.close();
            outputStream.close();
        }
    }
    jar.close();
}

private static void copyStream(InputStream inputStream, OutputStream outputStream) throws IOException {
    byte[] buffer = new byte[1024];
    int bytesRead;
    while ((bytesRead = inputStream.read(buffer)) != -1) {
        outputStream.write(buffer, 0, bytesRead);
    }
}
