import java.net.URL;
import java.util.jar.JarEntry;
import java.util.jar.JarFile;
import java.io.InputStream;

public static void addToClassPath(Vector<URL> cpV, String dir) {
    // Get the classpath
    URL classpathUrl = cpV.get(0);

    // Resolve the directory path
    String absDirPath = dir.replace("\\", "/");

    // Create a URI from the classpath URL
    URI classpathUri = URI.create(classpathUrl.toExternalForm());

    // Create a URI from the directory path
    URI dirUri = URI.create(absDirPath);

    // Create a URI by appending the directory path to the classpath URI
    URI jarDirUri = classpathUri.relativize(dirUri);

    // Create a URL from the jar directory URI
    URL jarDirUrl = file.toURI().resolve(jarDirUri).toURL();

    // Add the JR.jar file to the classpath
    cpV.add(jarDirUrl);
}
