import java.util.HashMap;
import java.util.Map;

public class IdentityGraphMapping<V, E> implements IsomorphicGraphMapping<V, E> {
    private Map<V, V> mapping;

    public IdentityGraphMapping(Graph<V, E> graph) {
        mapping = new HashMap<>();
        for (V vertex : graph.getVertices()) {
            mapping.put(vertex, vertex);
        }
    }

    @Override
    public V mapVertex(V oldVertex) {
        return mapping.get(oldVertex);
    }

    @Override
    public boolean canMap(V oldVertex, V newVertex) {
        return mapping.get(oldVertex) == newVertex;
    }

    @Override
    public E mapEdge(E oldEdge) {
        return oldEdge; // Identity mapping of edges
    }

    @Override
    public boolean canMap(E oldEdge, E newEdge) {
        return oldEdge.equals(newEdge); // Identity mapping of edges
    }
}
