    for (int v = 0; v < target.vertices(); v++) {
        V vertex = target.addVertex("V" + v);
        resultMap.put("V" + v, vertex);
    }

    for (V sourceVertex : resultMap.keySet()) {
        for (V targetVertex : resultMap.keySet()) {
            if (sourceVertex != targetVertex) {
                E edge = target.addEdge(sourceVertex, targetVertex);
                resultMap.get("V" + sourceVertex).addNeighbor(edge);
                resultMap.get("V" + targetVertex).addNeighbor(edge);
