override public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    int n = resultMap.size();
    V[] part1 = new V[n / 2];
    V[] part2 = new V[n - n / 2];
    V[] edges = new E[n];

    int index = 0;
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String name = entry.getKey();
        V vertex = entry.getValue();
        if (index < part1.length) {
            part1[index] = vertex;
        } else {
            part2[index - part1.length] = vertex;
        }
        index++;
    }

    for (int i = 0; i < part1.length; i++) {
        for (int j = 0; j < part2.length; j++) {
            edges[i * part2.length + j] = new Edge<>(part1[i], part2[j]);
        }
    }

    target.addAll(vertices(part1));
    target.addAll(vertices(part2));
    target.addAll(edges);
}
