    V partB = resultMap.get("partB");

    if (partA == null || partB == null) {
        throw new IllegalArgumentException("Part A or part B is not defined in the resultMap");
    }

    int numA = resultMap.getOrDefault("partANumber", 0);
    int numB = resultMap.getOrDefault("partBNumber", 0);

    if (numA <= 0 || numB <= 0) {
        throw new IllegalArgumentException("Number of vertices in part A or part B must be positive");
    }

    // Add edges from partA to partB
    for (int i = 0; i < numA; i++) {
        for (int j = 0; j < numB; j++) {
            target.add_edge(partA, partB);
        }
    }
}
