    long maxDuration = (int) FETCH_DATA_DURATION;
    List<TimeRange> timeRanges = new ArrayList<>();

    long currentStart = start;
    long currentEnd = start + maxDuration;

    while (currentEnd <= end) {
        timeRanges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
        currentEnd = currentStart + maxDuration;
    }

    // If there is any remaining time after the last full batch
