public static long compressTimeBucket(long timeBucket, int dayStep) {
    int part1 = (int) (timeBucket >> 32);
    int part2 = (int) (timeBucket & 0xFFFFFFFF);
    int compressedPart1 = part1;
    int compressedPart2 = part2;

    int iterationCount = 0;
    while (iterationCount < dayStep) {
        int lowerPart = part2 & 0x07FF; // Extract lower 11 bits
        int upperPart = part2 >> 11; // Extract upper 6 bits
        compressedPart1 ^= lowerPart ^ upperPart; // XOR operation for compression
        compressedPart2 ^= upperPart; // XOR operation for compression
        part2 = compressedPart1;
        iterationCount++;
    }

    return (compressedPart1 & 0xFFFFFFFF) << 32 | compressedPart2;
}
