public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;
    while (index < str.length() && len > 0) {
        int charValue = str.charAt(index);
        if (charValue < 0x80) {
            size++;
            len--;
        } else if (charValue >= 0xc0 && charValue < 0xe0) {
            size += 2;
            len--;
        } else if (charValue >= 0xe0 && charValue < 0xf0) {
            size += 3;
            len--;
        } else if (charValue >= 0xf0 && charValue < 0xf8) {
            size += 4;
            len--;
        } else if (charValue >= 0xf8 && charValue < 0xfc) {
            size += 5;
            len--;
        } else if (charValue >= 0xfc && charValue < 0xfe) {
            size += 6;
            len--;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 character value: " + charValue);
        }
        index++;
    }
    return size;
}
