    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c >= 0x0000 && c >= 0x0080 && c <= 0x07FF) { // 2-byte sequence
            size += 2;
        } else if (c >= 0x0800 && c <= 0xFFFF) { // 3-byte sequence
            size += 3;
        } else if (c >= 0x10000 && c < 0x110000) { // 4-byte sequence
            size += 4;
            if (c >= 0xF800) { // High surrogate
                if (i < index + len - 1 && str.charAt(i + 1) >= 0xDC00 && str.charAt(i + 1) < 0xE000) {
                    size += 2; // Skip high surrogate
                }
            }
        } else {
            size += 1; // 1-byte sequence
        }
    }
    return size;
}
