public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        int newSize = byteLength;
        byte[] newBytes = new byte[newSize];
        System.arraycopy(newBytes, 0, this.bytes, 0, newSize);
        return this;
    }
    if (byteOffset + byteLength > this.bytes.length) {
        int newLength = Math.max(this.bytes.length + byteLength, byteOffset + byteLength);
        byte[] newBytes = new byte[newLength];
        System.arraycopy(this.bytes, 0, newBytes, 0, byteOffset);
        System.arraycopy(byteArrayValue, byteOffset, newBytes, byteOffset, byteLength);
        System.arraycopy(this.bytes, byteOffset + byteLength, newBytes, byteOffset + byteLength, this.bytes.length - byteOffset - byteLength);
        this.bytes = newBytes;
    } else {
        System.arraycopy(byteArrayValue, byteOffset, this.bytes, byteOffset, byteLength);
    }
    return this;
}
