 sanctioned {
    public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
        IntSlice out = session.getWriteSlice(lb, str.length() * 3 + 3); // If the input size is 100, we need space for 300 bytes
        int i = out.getWritePos();
        while (i < str.length()) {
            int codepoint = str.codePointAt(i);
            if (codepoint >= 0xD800 && codepoint < 0xE000) { // High surrogate
                if (i + 1 < str.length()) {
                    if (str.codePointAt(i + 1) >= 0xDC00 && str.codePointAt(i + 1) < 0xF000) { // Low surrogate
                        codepoint = 0x10000 + ((codepoint - 0xD800) << 10) + (str.codePointAt(i + 1) - 0xDC00);
                        i++;
                    }
                } else {
                    throw new IllegalArgumentException("Unpaired surrogate");
                }
            }
            if (codepoint < 0) {
                throw new IllegalArgumentException("Unicode code point out of range");
            }
            out.putInt(codepoint);
            i += Character.charCount(codepoint);
        }
        session.setWritePos(out.getWritePos());
        return lb;
    }
}
