        if (decode) {
            path = URLDecoder.decode(path, "UTF-8");
        }

        String[] parts = path.split("/");
        for (String part : parts) {
            if (!part.isEmpty()) {
                pathSegments.add(new PathSegmentImpl(part));
            }
        }

