        char c = path.charAt(i);
        if (c == '/' && (segmentBuilder.length() > 0 || decode)) {
            segments.add(PathSegmentImpl.decode(segmentBuilder.toString(), decode));
            segmentBuilder.setLength(0);
        } else {
            segmentBuilder.append(c);
        }
    }

    if (segmentBuilder.length() > 0) {
        segments.add(PathSegmentImpl.decode(segmentBuilder.toString(), decode));
    }

    return segments;
}
```

```java
public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return Collections.emptyList();
    }

    List<PathSegmentImpl> segments = new ArrayList<>();
    for (String segment : path.split("/")) {
        if (!decode || isEncoded(segment)) {
            segments.add(new PathSegmentImpl(segment));
        } else {
            segments.add(new PathSegmentImpl(decodePath(segment, false)));
        }
    }

    return segments;
}

private static boolean isEncoded(String segment) {
    return segment != null &&
           segment.startsWith("%") &&
           segment.length() > 2 &&
           Character.isDigit(segment.charAt(1)) &&
           Character.isDigit(segment.charAt(2));
}
