        throw new IllegalArgumentException("Box cannot be null");
    }
    double width = box.getMaxX() - box.getMinX();
    double halfWidth = width / 2;
    return new Pair<>(new Box2D(box.getMinX(), box.getMinY(), halfWidth, box.getHeight()), new Box2D(box.getMinX() + halfWidth, box.getMinY(), box.getMaxX() - halfWidth, box.getHeight()));
}
