public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }

    int size = node.getContentSize();
    out.writeObject(node.getDataPointer());
    out.writeInt(size);

    if (node.getChildren() != null) {
        size += writeTo(out, node.getChildren());
    }

    if (node.getReferences() != null) {
        size += writeTo(out, node.getReferences());
    }

    return size;
}
