private int readStream(InputStream in) throws IOException {
    final int bufferSize = 4096;
    final byte[] buffer = new byte[bufferSize];
    int bytesRead;
    while ((bytesRead = in.read(buffer)) != -1) {
        int index = readPointer;
        int bytesToWrite = Math.min(bytesRead, capacity - index);
        System.arraycopy(buffer, 0, buffer, index, bytesToWrite);
        readPointer += bytesToWrite;
        capacity = Math.max(capacity, readPointer);
    }
    return bytesRead;
}

public void readFrom(final InputStream in) throws IOException {
    int bytesRead = readStream(in);
    while (bytesRead > 0) {
        readPointer = 0;
        bytesRead = readStream(in);
    }
}
