public static int nextPrime(int desiredCapacity){
    if (desiredCapacity < 2) return 2;
    int max = desiredCapacity * 11 / 10; // Max within 11%
    while(true) {
        int next = getNextPrime(max);
        if (next >= desiredCapacity) return next;
