private static int getNextPrime(int n) {
    for (int i = 2; i * i <= n; increment(i)) {
        if (isPrime(i)) return i;
    }
    return n;
}

private static void increment(int n) {
    boolean found = false;
    for (int i = n; i <= Integer.MAX_VALUE; i++) {
        if (isPrime(i)) {
            n = i;
            found = true;
            break;
        }
    }
    if (!found) {
        System.out.println("No prime number found!");
    }
}

private static boolean isPrime(int n) {
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0) return false;
    return n > 1;
}
