public static String javaCharset(String charset){
    if (charset == null) {
        return null;
    }

    // Mime charset name to Java charset mapping
    Map<String, String> mimeToJavaCharset = new HashMap<>();
    mimeToJavaCharset.put("US-ASCII", "ISO-8859-1");
    mimeToJavaCharset.put("ISO-8859-2", "ISO-8859-2");
    mimeToJavaCharset.put("ISO-8859-3", "ISO-8859-3");
    mimeToJavaCharset.put("ISO-8859-4", "ISO-8859-4");
    mimeToJavaCharset.put("ISO-8859-5", "ISO-8859-5");
    mimeToJavaCharset.put("ISO-8859-6", "ISO-8859-6");
    mimeToJavaCharset.put("ISO-8859-7", "ISO-8859-7");
    mimeToJavaCharset.put("ISO-8859-8", "ISO-8859-8");
    mimeToJavaCharset.put("ISO-8859-9", "ISO-8859-9");
    mimeToJavaCharset.put("ISO-8859-10", "ISO-8859-10");
    mimeToJavaCharset.put("ISO-8859-11", "ISO-8859-11");
    mimeToJavaCharset.put("ISO-8859-12", "ISO-8859-12");
    mimeToJavaCharset.put("ISO-8859-13", "ISO-8859-13");
    mimeToJavaCharset.put("ISO-8859-14", "ISO-8859-14");
    mimeToJavaCharset.put("ISO-8859-15", "ISO-8859-15");

    // Standard charset to avoid processing
    if (mimeToJavaCharset.containsKey(charset)) {
        return mimeToJavaCharset.get(charset);
    }

    // Special case for Windows-1252
    if (charset.equalsIgnoreCase("windows-1252")) {
        return "windows-1252";
    }

    // Encode charset as ISO8859-1 and prepend with "x-"
    try {
        byte[] bytes = charset.getBytes("ISO-8859-1");
        return "x-" + new String(bytes);
    } catch (UnsupportedEncodingException e) {
        return null; // Unknown charset
    }
}
