private static <T> T[] copyArrayGrow1(final T[] array, final Class<T> newArrayComponentType) {
    // Check if the input array is null
    if (array == null) {
        // Create a new array of the same type but with a size of 1
        returnnewInstance(newArrayComponentType, 1);
    }

    // If there is enough length to append one more element without reallocation
    if (array.length >= array.length + 1) {
        return array;
    }

    // Create a new array with one more element than the input array
    T[] newArray =newInstance(newArrayComponentType, array.length + 1);

    // Copy all elements from the input array to the new array
    System.arraycopy(array, 0, newArray, 0, array.length);

    // Return the new array
    return newArray;
}

private static <T> T[] newInstance(final Class<T> type, final int length) {
    try {
        // Get the default constructor of the given class
        return type.getDeclaredConstructor().newInstance();
    } catch (Exception e) {
        throw new RuntimeException("Error creating new array of type " + type.getName(), e);
    }
}
