private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException("Array and newArrayComponentType must not be null");
        }
        // Create a new array of the specified type with 1 element
        return newArrayComponentType.cast(Array.newInstance(newArrayComponentType, 1));
    }

    // Create a new array of size 1 greater than the input array
    Object newArray = Array.newInstance(array.getClass().getComponentType(), Array.getLength(array) + 1);

    // Copy each element from the input array to the new array
    for (int i = 0; i < Array.getLength(array); i++) {
        Array.set(newArray, i, Array.get(array, i));
    }

