private int computeBinaryLog(int n) {
    // Logarithm for negative numbers is undefined.
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative.");
    }

    // Base case for recursion: log2(1) = 0 and log2(n) >= 0 for all n > 0.
    if (n == 1) {
        return 0;
    }

    // Recursive case: log2(n) = 1 + log2(n//2)
    return 1 + computeBinaryLog(n / 2);
}
