    byte[] value = readConstVal(constantPoolEntryIndex);
    int length = (value[0] & 0xff) | ((value[1] & 0xff) << 8);
    int utf8Length = 0;
    for (int i = length - 1; i >= 0; i--) {
        if ((value[i] & 0xe0) == 0xe0) {
            utf8Length = 3;
        } else if ((value[i] & 0xc0) == 0xc0) {
            utf8Length = 2;
        } else {
            utf8Length = 1;
        }
        if (i == 0) {
            break;
        }
        i--;
    }
    for (int i = 0; i < utf8Length && i < value.length; i++) {
        charBuffer[i] = (char) ((value[i] & 0xff) | ((value[i + 1] & 0xff) << 8));
        i++;
    }
    return new String(charBuffer);
