    public final MatchResult match(CharSequence uri) {
        Matcher matcher = pattern.matcher(uri);
        if (matcher.find()) {
            int uriPosition = matcher.start();
            int templatePosition = 0;
            MatchResult result = new MatchResult();
            while (uriPosition < uri.length() && templatePosition < template.length()) {
                char uriChar = uri.charAt(uriPosition);
                char templateChar = template.charAt(templatePosition);
                if (uriChar == templateChar) {
                    uriPosition++;
                    templatePosition++;
                    result.addMatch(uriChar);
                } else if (uriChar == '%') {
