import java.util.Iterator;
import java.util.Set;

public class GraphUtils {

    /**
     * Transform from a Set representation to a graph path.
     * @param tour a set containing the edges of the tour
     * @param graph the graph
     * @return a graph path
     */
    protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        // Create a new GraphPath instance
        GraphPath<V, E> path = new GraphPath<>();

        // Use an iterator to navigate through the tour set
        Iterator<E> iterator = tour.iterator();

        if (!iterator.hasNext()) {
            return path;  // Return an empty path if the tour set is empty
        }

        // Get the first edge from the tour set
        E edge = iterator.next();
        path.addVertex(edge.getOrigin());  // Add the origin vertex to the path
        path.addEdge(edge);  // Add the edge to the path

        // Continue adding vertices and edges until all edges in the tour set are processed
        while (iterator.hasNext()) {
            edge = iterator.next();
            path.addVertex(edge.getDest());  // Add the destination vertex to the path
            path.addEdge(edge);  // Add the edge to the path
        }

        return path;  // Return the complete graph path
    }

}
```

