protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph){
    GraphPath<V, E> path = new GraphPath<>();

    Vertex<V> startVertex = null;
    for (E edge : tour) {
        if (startVertex == null) {
            startVertex = graph.getVertex(edge.getStart());
        }
        path.addVertex(startVertex);
        path.addEdge(startVertex, graph.getVertex(edge.getEnd()));
        startVertex = graph.getVertex(edge.getEnd());
    }

    return path;
}
