private String unescapeId(String input) {
    if (input == null) {
        return null;
    }

    StringBuilder escaped = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == DOT) {
            if (i < input.length() - 1 && input.charAt(i + 1) == DOT) {
                // Escape .. using ..
                escaped.append(DOT).append(DOT);
                i++;
            } else {
                // Escape .
                escaped.append(DOT);
            }
        } else {
            escaped.append(c);
        }
    }

    return escaped.toString();
}
