boolean unlink(ListNodeImpl<E> node) {
    // Get the previous node
    ListNodeImpl<E> previous = node.getPrevious();
    // Get the next node
    ListNodeImpl<E> next = node.getNext();
    // Check if node is the first in the list
    if (previous == null) {
        list.head = next; // If it is the first node, set the list head to the next node
        next.setPrevious(null); // Set the previous of the next node to null
    } else {
        // Otherwise, set the previous of the next node to the previous node
        next.setPrevious(previous);
    }
    // Check if node is the last in the list
    if (next == null) {
        list.tail = previous; // If it is the last node, set the list tail to the previous node
        previous.setNext(null); // Set the next of the previous node to null
    } else {
        // Otherwise, set the next of the previous node to the next node
        previous.setNext(next);
    }
    // Remove the node from the list
    node.clear();
    return true;
}
