    while (currentNode != null) {
        currentNode.prev = null; // Break doubly linked list connection
        ListNode<E> nextNode = currentNode.next;
        addListNode(currentNode); // Add current node to this list
        currentNode = nextNode; // Move to the next node
    }
    list.head = null; // Reinitialize list head
}
