public static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.isEmpty() || graph.vertexSet().size() - vertices.size() < vertices.size() / 2) {
        return true;
    }

    for (V vertex : vertices) {
        Set<E> neighbors = graph.edgesOf(vertex).stream()
                                        .map(Edge::otherVertex)
                                        .collect(Collectors.toSet());

        for (V neighbor : vertices) {
            if (!neighbors.contains(neighbor)) {
                return false;
            }
        }
    }

    return true;
}
