public static String encodeTemplateNames(String s){
    if (s == null || s.isEmpty()) {
        return s;
    }

    StringBuilder encoded = new StringBuilder();
    int i = 0;

    while (i < s.length()) {
        if (s.charAt(i) == '{') {
            encoded.append("%7B");
            // Skip one character to get the following character
            i++;
        } else if (s.charAt(i) == '}') {
            encoded.append("%7D");
            // Skip one character to get the following character
            i++;
        } else {
            encoded.append(s.charAt(i));
            i++;
        }
    }

    return encoded.toString();
}
