    BufferedReader reader = null;
    try {
        reader = new BufferedReader(new FileReader(file));
        String line;
        while ((line = reader.readLine()) != null) {
            // Parse and process the line as ThreadSnapshot
            // Example parsing logic:
            String[] parts = line.split(",");
            if (parts.length >= 3) {
                String threadId = parts[0];
                String time = parts[1];
                String snapshotData = parts[2];
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, time, snapshotData);
                threadSnapshots.add(threadSnapshot);
            }
        }
    } finally {
        if (reader != null) {
            reader.close();
        }
    }
    return threadSnapshots;
}
