    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    FileReader fileReader = new FileReader(file);
    BufferedReader bufferedReader = new BufferedReader(fileReader);

    String line;
    while ((line = bufferedReader.readLine()) != null) {
        // Parse the line and create a ThreadSnapshot object
        ThreadSnapshot threadSnapshot = new ThreadSnapshot(line);
        threadSnapshots.add(threadSnapshot);

        // Check if the current thread is within any指定的时间范围
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (threadSnapshot.isActiveInTimeRange(timeRange)) {
                // Perform action if the thread is active within the time range
                performActionOnActiveThread(threadSnapshot);
                break;
            }
        }
    }

    bufferedReader.close();
    fileReader.close();

    System.out.println("Parsing completed successfully.");
    return threadSnapshots;
}

